def _check_dependents(gpx_object: Any, fieldname: str) ->Tuple[str, str]:
    fields = gpx_object.gpx_10_fields + gpx_object.gpx_11_fields
    for field in fields:
        if isinstance(field, str):
            if field == fieldname:
                return (fieldname, fieldname)
        else:
            if hasattr(field, 'name') and field.name == fieldname:
                return (fieldname, fieldname)
    return (fieldname, fieldname)

def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if not prettyprint:
        indent = ''
    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = fields + instance.gpx_11_fields

    tag_open = f'\n{indent}<{tag}'
    body = []
    attributes = []

    if custom_attributes:
        for key, value in custom_attributes.items():
            attributes.append(f' {key}="{value}"')

    for field in fields:
        if isinstance(field, str):
            continue
        if field.attribute:
            value = getattr(instance, field.name)
            xml_value = field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=indent + '  ')
            if xml_value:
                attributes.append(f' {xml_value}')
        else:
            value = getattr(instance, field.name)
            xml_value = field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=indent + '  ')
            if xml_value:
                body.append(xml_value)

    result = [tag_open]
    result.extend(attributes)

    if body or empty_body:
        result.append('>')
        result.extend(body)
        if prettyprint and body:
            result.append(f'\n{indent}')
        result.append(f'</{tag}>')
    else:
        result.append(' />')

    return ''.join(result)

def gpx_fields_from_xml(class_or_instance: Any, node: str, version: str) ->Any:
    if mod_inspect.isclass(class_or_instance):
        instance = class_or_instance()
    else:
        instance = class_or_instance

    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = fields + instance.gpx_11_fields

    for field in fields:
        if isinstance(field, str):
            continue
        value = field.from_xml(node, version)
        if value is not None:
            setattr(instance, field.name, value)
        elif field.is_list:
            setattr(instance, field.name, [])

    return instance

def __init__(self, s: str='') ->None:
    self.offset = 0
    if s and len(s) >= 2:
        if s[0] in ('−', '-'):
            mult = -1
            s = s[1:]
        else:
            if s[0] == '+':
                s = s[1:]
            mult = 1
        hour = int(s[:2]) if s[:2].isdigit() else 0
        if len(s) >= 4:
            minute = int(s[-2:]) if s[-2:].isdigit() else 0
        else:
            minute = 0
        self.offset = mult * (hour * 60 + minute)

def to_xml(self, value: Any, version: str, nsmap: Any=None, prettyprint:
    bool=True, indent: str='') ->Optional[str]:
    if value is None:
        return ''
    if not prettyprint:
        indent = ''
    if self.attribute:
        return f'{self.attribute}="{mod_utils.make_str(value)}"'
    elif self.type_converter:
        value = self.type_converter.to_string(value)
    if self.tag:
        return mod_utils.to_xml(self.tag, content=value, escape=True,
                                prettyprint=prettyprint, indent=indent)
    return ''

