    prettyprint: bool=True, indent: str='') ->str:
    if not prettyprint:
        indent = ''
    if self.is_list:
        result = []
        for obj in value:
            result.append(gpx_fields_to_xml(obj, self.tag, version,
                                            nsmap=nsmap,
                                            prettyprint=prettyprint,
                                            indent=indent))
        return ''.join(result)
    else:
        return gpx_fields_to_xml(value, self.tag, version, nsmap=nsmap, prettyprint=prettyprint, indent=indent, empty_body=self.empty_body)

def from_xml(self, node: Any, version: str) ->Any:
    result: Any = []
    extensions_node = node.find(self.tag)
    if extensions_node is None:
        return result
    for child in extensions_node:
        result.append(mod_copy.deepcopy(child))
    return result

def _ETree_to_xml(self, node: Any, nsmap: Dict[str, str]={}, prettyprint:
    bool=True, indent: str='') ->str:
    if not prettyprint:
        indent = ''

    result = []
    prefixedname = self._resolve_prefix(node.tag, nsmap)
    result.append(f'\n{indent}<{prefixedname}')
    for attrib, value in node.attrib.items():
        attrib = self._resolve_prefix(attrib, nsmap)
        result.append(f' {attrib}="{value}"')
    result.append('>')
    if node.text is not None:
