    tail = node.tail
    if tail is not None:
        tail = mod_saxutils.escape(tail.strip())
    else:
        tail = ''
    if len(node) > 0:
        result.append(f'\n{indent}')
    result.append(f'</{prefixedname}>{tail}')

    return ''.join(result)

def to_xml(self, value: Any, version: str, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='') ->str:
    if not prettyprint:
